CREATE UNIQUE INDEX ceo_workday_plan_items_plan_job_uniq ON public.ceo_workday_plan_items USING btree (plan_id, job_id) WHERE (job_id IS NOT NULL);
CREATE INDEX ceo_workday_plan_items_job_idx ON public.ceo_workday_plan_items USING btree (job_id) WHERE (job_id IS NOT NULL);
CREATE INDEX business_profile_facts_user_category_idx ON public.business_profile_facts USING btree (user_id, category_key, sort_order);
