CREATE INDEX ceo_workday_plans_user_date_idx ON public.ceo_workday_plans USING btree (user_id, plan_date DESC);
CREATE INDEX boss_team_members_user_idx ON public.boss_team_members USING btree (user_id);
CREATE INDEX boss_job_proposals_job_idx ON public.boss_job_proposals USING btree (user_id, job_id, created_at DESC);
CREATE INDEX idx_user_profiles_email ON public.user_profiles USING btree (email);
